'use strict';
// Source-based arithmetic and input-boundary regressions, not predictive validation.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict'),acorn=require('acorn');
const {environment}=require('./dom-fixture.cjs');
const root=path.resolve(__dirname,'..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),plain=x=>JSON.parse(JSON.stringify(x));
let count=0;function test(name,f){try{f();count++;console.log('PASS '+name);}catch(e){process.exitCode=1;console.error('FAIL '+name+'\n'+e.stack);}}
function load(c,f){vm.runInContext(read(f),c,{filename:f});}
const {ctx:c}=environment();
['JS/vendor/lunar.js','JS/bazi-calendar-core.js','JS/solar-location.js','JS/bazi.js','JS/bazi-suite-core.js'].forEach(f=>load(c,f));
const a=read('JS/ai-analysis.js'),ast=acorn.parse(a,{ecmaVersion:'latest'});
for(const node of ast.body){
 if(node.type==='VariableDeclaration'&&node.declarations.some(d=>['SIHUA_TABLE','ZW_PALACES','ZW_MAJOR','ZW_BRIGHTNESS'].includes(d.id.name)))vm.runInContext(a.slice(node.start,node.end),c);
 if(node.type==='FunctionDeclaration'&&node.id.name==='getStarBright')vm.runInContext(a.slice(node.start,node.end),c);
}
c.Lunar.Solar=c.Solar;load(c,'JS/ziwei.js');
const branches='子丑寅卯辰巳午未申酉戌亥';
function chartLunar(y,m,d,h=0,gender='male',opts={}){const s=c.Lunar.fromYmd(y,m,d).getSolar();const r=c.computeZiwei(s.getYear(),s.getMonth(),s.getDay(),h,gender,opts);assert(r,c._jyZiweiError);return r;}
function starAt(z,name,type){const p=z.palaces.find(p=>p.stars.some(s=>s.name===name&&(!type||s.type===type)));assert(p,name);return p.branch;}
// Frozen rows independently walked using the published 補数奇退偶進 instruction.
const anchors={
2:'丑寅寅卯卯辰辰巳巳午午未未申申酉酉戌戌亥亥子子丑丑寅寅卯卯辰',
3:'辰丑寅巳寅卯午卯辰未辰巳申巳午酉午未戌未申亥申酉子酉戌丑戌亥',
4:'亥辰丑寅子巳寅卯丑午卯辰寅未辰巳卯申巳午辰酉午未巳戌未申午亥',
5:'午亥辰丑寅未子巳寅卯申丑午卯辰酉寅未辰巳戌卯申巳午亥辰酉午未',
6:'酉午亥辰丑寅戌未子巳寅卯亥申丑午卯辰子酉寅未辰巳丑戌卯申巳午'
};
test('紫微定位：五種局 × 三十日，150格固定安星表',()=>{for(const [ju,row] of Object.entries(anchors)){assert.equal(row.length,30);for(let d=1;d<=30;d++)assert.equal(branches[c.getZiweiPalaceByJu(+ju,d)],row[d-1],ju+'局'+d+'日');}assert.throws(()=>c.getZiweiPalaceByJu(3,0));assert.throws(()=>c.getZiweiPalaceByJu(7,2));});
test('命身宮：144個月時组合；十四主星不重複、宮位完整',()=>{for(let m=1;m<=12;m++)for(let shi=0;shi<12;shi++){const z=chartLunar(2008,m,12,shi*2);let ming=1+m,shen=1+m;for(let i=0;i<shi;i++){ming--;shen++;}assert.equal(z.palaces[0].branch,branches[(ming+24)%12]);assert.equal(z.palaces.find(p=>p.isShen).branch,branches[shen%12]);const majors=z.palaces.flatMap(p=>p.stars.filter(s=>s.type==='major'));assert.equal(majors.length,14);assert.equal(new Set(majors.map(x=>x.name)).size,14);assert.equal(new Set(z.palaces.map(x=>x.branch)).size,12);assert.equal(z.sihua.length,4);}});
test('五行局：六十甲子納音表，非法干支拒算',()=>{const nayin='金火木土金火水土金木水土火木水金火木土金火水土金木水土火木水';const stems='甲乙丙丁戊己庚辛壬癸',map={金:4,木:3,水:2,火:6,土:5};for(let n=0;n<60;n++)assert.equal(c.getWuxingJu(stems[n%10],branches[n%12]),map[nayin[Math.floor(n/2)]]);assert.throws(()=>c.getWuxingJu('甲','丑'));});
test('年系星逐支查表；命主命宮取值；來因宮排除子丑重複干',()=>{const fei='申酉戌巳午未寅卯辰亥子丑',po='巳丑酉巳丑酉巳丑酉巳丑酉',dahao='未午酉申亥戌丑子卯寅巳辰',minor='戌未辰丑戌未辰丑戌未辰丑',rulers=['貪狼','巨門','祿存','文曲','廉貞','武曲','破軍','武曲','廉貞','文曲','祿存','巨門'];for(let i=0;i<12;i++){let z=chartLunar(1984+i,4,8,14);assert.equal(starAt(z,'蜚廉'),fei[i]);assert.equal(starAt(z,'破碎'),po[i]);assert.equal(starAt(z,'大耗','minor2'),dahao[i]);assert.equal(z.getXiaoXian(1).branch,minor[i]);assert.equal(z.mingZhu,rulers[z.mingIdx]);assert(!['子','丑'].includes(z.laiYin.branch));}});
test('月、日、時系星：解神、天巫、陰煞、天貴、恩光、封誥與天壽',()=>{const jieshen='申申戌戌子子寅寅辰辰午午',tianwu='巳申寅亥巳申寅亥巳申寅亥',yin='寅子戌申午辰寅子戌申午辰';for(let m=1;m<=12;m++){const z=chartLunar(2008,m,1,0);assert.equal(starAt(z,'解神'),jieshen[m-1]);assert.equal(starAt(z,'天巫'),tianwu[m-1]);assert.equal(starAt(z,'陰煞'),yin[m-1]);assert.equal(starAt(z,'天貴'),'卯');assert.equal(starAt(z,'恩光'),'酉');assert.equal(starAt(z,'封誥'),'寅');assert.equal(starAt(z,'天傷'),z.palaces[7].branch);assert.equal(starAt(z,'天壽'),z.palaces.find(p=>p.isShen).branch);}});
test('曆法：2023閏二月、2025閏六月、2026農曆新年；兩種閏月政策',()=>{const a=c.approxLunar(2023,3,22);assert.deepEqual([a.year,a.month,a.day,a.isLeap],[2023,2,1,true]);const b=c.approxLunar(2025,7,25);assert.deepEqual([b.month,b.day,b.isLeap],[6,1,true]);assert.equal(c.approxLunar(2026,2,17).day,1);const same=chartLunar(2023,-2,20),split=chartLunar(2023,-2,20,0,'male',{leapMonthPolicy:'SPLIT_AT_15'});assert.equal(same.calculationPolicy.effectiveMonth,2);assert.equal(split.calculationPolicy.effectiveMonth,3);assert.equal(same.birthLunar.month,2);assert(same.birthLunar.isLeap);assert.notEqual(same.mingIdx,split.mingIdx);});
test('晚子時可分早晚；月底子初換日與正月初一虛歲',()=>{let a=c.computeZiwei(2026,2,16,23,'male',{dayBoundaryMode:'MIDNIGHT_00',referenceDate:'2026-02-16T00:00:00Z'}),b=c.computeZiwei(2026,2,16,23,'male',{dayBoundaryMode:'ZI_HOUR_23',referenceDate:'2026-02-17T00:00:00Z'});assert.equal(a.lunar.year,2025);assert.equal(b.lunar.year,2026);assert.equal(b.lunar.day,1);const old=chartLunar(2008,1,1,0,'male',{referenceDate:'2026-02-16T00:00:00Z'}),next=chartLunar(2008,1,1,0,'male',{referenceDate:'2026-02-17T00:00:00Z'});assert.equal(old.currentAge,18);assert.equal(next.currentAge,19);});
test('斗君：2008正月子時生，2026正月命宮午；四月未時生則戌',()=>{assert.equal(chartLunar(2008,1,1).getLiuYueZw(2026)[0].mingBranch,'午');assert.equal(chartLunar(2008,4,1,14).getLiuYueZw(2026)[0].mingBranch,'戌');});
test('八字：節氣依同一UTC瞬間，時區及真太陽時不改年、月柱',()=>{for(const instant of ['2026-02-03T19:55:00Z','2026-02-03T20:10:00Z']){let outputs=[];for(const loc of [[121.56,8,'Asia/Taipei'],[-74,-5,'America/New_York'],[0,0,'Europe/London']]){const date=new Date(Date.parse(instant)+loc[1]*3600000),s=c.calcTrueSolarTime(date.getUTCFullYear(),date.getUTCMonth()+1,date.getUTCDate(),date.getUTCHours(),date.getUTCMinutes(),...loc);const fact=c.BaziCalendarCore.calculateChart({...s,birthInstant:s.utcTimestamp,trueSolarTimeApplied:true});outputs.push(fact.pillars.year.gan+fact.pillars.year.zhi+' '+fact.pillars.month.gan+fact.pillars.month.zhi);}assert.equal(new Set(outputs).size,1);assert.equal(outputs[0],instant.includes('19:55')?'乙巳 己丑':'丙午 庚寅');}});
test('八字：日柱基準、23點兩種政策、節氣引擎缺失與不存在日期',()=>{let x=c.BaziCalendarCore.calculateChart({year:2000,month:1,day:7,hour:12});assert.equal(x.pillars.day.gan+x.pillars.day.zhi,'甲子');let a=c.BaziCalendarCore.calculateChart({year:2000,month:1,day:7,hour:23,dayBoundaryMode:'MIDNIGHT_00'}),b=c.BaziCalendarCore.calculateChart({year:2000,month:1,day:7,hour:23,dayBoundaryMode:'ZI_HOUR_23'});assert.equal(a.pillars.day.gan,'甲');assert.equal(a.pillars.hour.gan,'甲');assert.equal(b.pillars.day.gan,'乙');assert.equal(b.pillars.hour.gan,'丙');assert.throws(()=>c.computeBazi(2026,2,30,12,0,'male'));let core=c.BaziCalendarCore;c.BaziCalendarCore=null;assert.throws(()=>c.computeBazi(2000,1,7,12,0,'male'),/停止/);c.BaziCalendarCore=core;});
test('合盤：100種有方向的十神，不把A看B反寫成B看A',()=>{const stems='甲乙丙丁戊己庚辛壬癸';const table=[['比肩','劫財','食神','傷官','偏財','正財','七殺','正官','偏印','正印'],['劫財','比肩','傷官','食神','正財','偏財','正官','七殺','正印','偏印']];for(let i=0;i<10;i++)for(let j=0;j<10;j++){const rel=(j-Math.floor(i/2)*2+10)%10;assert.equal(c.BaziSuiteCore.tenGod(stems[i],stems[j]),table[i%2][rel]);assert.equal(c.tenGod(stems[i],stems[j]),table[i%2][rel]);}});
test('起運：分鐘距離按三日一年折算，正逆取節、不偽稱秒級準確',()=>{for(const gender of ['male','female']){const s=c.calcTrueSolarTime(1983,8,25,14,55,120.23,8,'Asia/Taipei');const y=c.BaziCalendarCore.calculateYun({...s,gender,birthInstant:s.utcTimestamp,trueSolarTimeApplied:true});const distance=Math.abs(Date.parse(y.referenceJieDate.replace(' ','T')+'+08:00')-s.utcTimestamp)/60000;const truncatedMinutes=Math.floor(distance);assert.equal(y.years,Math.floor(truncatedMinutes/4320));assert.equal(y.months,Math.floor((truncatedMinutes%4320)/360));assert.equal(y.days,Math.floor((truncatedMinutes%360)/12));assert.equal(y.precision,'minute');}});
const fixtures=JSON.parse(read('tests/fixtures/accuracy-sources-20260912.json'));
test('香港天文台三年逐月月首：36個獨立日期（含閏月）',()=>{const months=['正','二','三','四','五','六','七','八','九','十','十一','十二'];let n=0;for(const batch of fixtures.hko)for(const row of batch.rows){const m=row.match(/(\d+)年(\d+)月(\d+)日\s+(閏?)([正一二三四五六七八九十]+)月/);if(!m)continue;const lunar=c.approxLunar(+m[1],+m[2],+m[3]);assert.equal(lunar.month,months.indexOf(m[5])+1,row);assert.equal(lunar.day,1,row);assert.equal(lunar.isLeap,!!m[4],row);n++;}assert.equal(n,36);});
test('二十顆星 × 十二宮廟旺表；未知星不虛填平',()=>{for(const [star,values]of Object.entries(fixtures.brightness.table))for(let i=0;i<12;i++)assert.equal(c.getStarBright(star,i).label,values[i],star+branches[i]);assert.equal(c.getStarBright('未登錄星',0).label,'');});
test('八字命宮與紫微宮位口徑分開；ISO出生瞬間可核對',()=>{const g=c.getMingGong(0,4,10,3);assert.equal(g.zhi,'卯');const b=c.computeBazi(2000,1,7,12,0,'male',{birthInstant:'2000-01-07T04:00:00Z'});assert.equal(b.calculationPolicy.birthInstant,'2000-01-07T04:00:00.000Z');assert.throws(()=>c.computeBazi(2000,1,7,12,0,'male',{birthInstant:'bad'}),/瞬間/);});
test('跨系統整合不修改八字分數、不以相同歲數誤配虛歲',()=>{c.S.bazi={dayun:[{score:2,level:'原值',ageStart:6,ageEnd:15}]};c.S.ziwei=chartLunar(2008,4,8);c.mergeZiweiIntoBazi();assert.equal(c.S.bazi.dayun[0].score,2);assert.equal(c.S.bazi.dayun[0].level,'原值');assert.equal(c.S.bazi.ziweiReference.policy,'SEPARATE_SYSTEMS_NO_SCORE_MERGE');});
console.log('Source arithmetic groups passed: '+count);
